case 15:printf("{\"preference\":%u,\"host\":",r->data.mx->preference);str(r->data.mx->mxhost);putchar('}');break;
case 33:printf("{\"priority\":%u,\"weight\":%u,\"port\":%u,\"target\":",r->data.srv->priority,r->data.srv->weight,r->data.srv->port);str(r->data.srv->target);putchar('}');break;
